using System;using System.Text;using UnityEngine;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckDodgeball {
public enum DodgeStage{Countdown,Playing,Replay,RoundResult}
public sealed class DodgeMatch:SportsEventSession {
 public override bool BroadcastParticipantActive(int slot)=>rules.alive[slot];
 public override void DescribeBroadcast(SportsBroadcastAction a,SportsBroadcastFraming f){int slot=f.Nearest(f.RequestedFocus,true);if(slot<0)slot=f.Nearest(f.RequestedFocus);a.primary=slot;if(slot<0)return;int best=-1;float distance=float.PositiveInfinity;for(int i=0;i<balls.Length;i++)if(balls[i].gameObject.activeInHierarchy){float d=(balls[i].body.position-f.Body(slot).position).sqrMagnitude;if(d<distance){distance=d;best=i;}}if(best>=0)a.Objective(balls[best].body.position,1);a.reason="DODGEBALL / LIVE ATTACK OR RETURN";}
 public DodgeFighter[] fighters;public DodgeBall[] balls;public SportsRallyViews views;public SportsCameraFit fit;public SportsMotionReplay replay;public DodgeReplayColors replayColors;public DodgeRules rules=new DodgeRules();public float suddenDeath=75,roundLimit=105,strikeSpeed=14,suddenStrikeSpeed=18,strikeLift=6.5f;
 public DodgeStage Stage{get;private set;}public float Clock{get;private set;}public float Timer{get;private set;}public int BounceCount{get;set;}public int StrikeCount{get;set;}public int Eliminations{get;private set;}public int Returns{get;private set;}public int StrikeContests{get;private set;}public int Neutralizations{get;private set;}public int Draws{get;private set;}public int GroundContacts{get;private set;}public int FriendlyContacts{get;private set;}public int QueuedContacts{get;private set;}public int ContactPeak{get;private set;}
 struct BallContact {public int ball,target,flight;public bool ground;public float time;}
 readonly BallContact[] contacts=new BallContact[64];int contactCount;readonly Vector2[] ai=new Vector2[8];readonly float[] think=new float[8],stuck=new float[8],back=new float[8];readonly bool[] aiStrike=new bool[8];readonly int[] seenFlight=new int[8],seenBall=new int[8];readonly float[] threatSince=new float[8];readonly bool[] attemptReturn=new bool[8];readonly StringBuilder text=new StringBuilder(700);string notice="";bool skip;float replayAge;readonly bool[] airborne=new bool[8];
 public override string Title=>"TRAMPOLINE DODGEBALL";public override int MinimumPlayers=>2;public override int MaximumPlayers=>8;public override bool TeamSport=>true;public override int OptionCount=>2;public override int WeatherCount=>1;public override string OptionLabel=>option==0?"SHARED ARENA VIEW":"SPLIT-SCREEN CHASE";public override bool ReplayControls=>Stage==DodgeStage.Replay;public override bool MultiViewHUD=>option==1&&views!=null&&views.Humans>0;
 public override string Help=>"FIRST TEAM TO THREE · TRAMPOLINE DODGEBALL\nOne to four trucks per team; up to four humans and named AI. Drive, brake before reversing, and bounce from actual trampoline contact. Limited directional aftertouch nudges flight; it cannot sustain flight.\n\nPress your assigned ACTION to strike in a short visible forward window. It works on the ground or in the air, returns a nearby incoming ball, and has a cooldown. Face your intended target. A struck ball takes your team's color. A live opposing ball eliminates a vulnerable truck. Your own team's ball is safe; the striker also receives a short launch grace. Ground contact returns a ball to cream NEUTRAL. One contact cannot eliminate a crowd. Landing on the trampoline never eliminates a truck.\n\nLast surviving team wins. All contacts within a physics step are ordered before resolving the teams; a simultaneous wipe draws and replays the round. At 75 seconds SUDDEN DEATH increases legal strike speed for everyone; at 105 seconds an unresolved round explicitly draws. No hidden homing or immunity. Shared arena view is the default; human chase split-screen is selectable. Replays show the actual recorded flight and ball colors, with angle, slow/fast, rewind and skip. Pause/reconnect preserves the round. Offline only.";
 public override string Header=>Title+" · ROUND "+rules.Round+" · "+rules.wins[0]+" : "+rules.wins[1]+" · "+(Stage==DodgeStage.Countdown?Mathf.CeilToInt(Timer).ToString():Stage==DodgeStage.Playing?Mathf.Max(0,roundLimit-Clock).ToString("F0")+"s":Stage.ToString().ToUpperInvariant());
 public override string Status=>Stage==DodgeStage.Playing?(Clock>=suddenDeath?"SUDDEN DEATH · FASTER STRIKES · ":"")+"BLUE vs ORANGE · CREAM BALL = NEUTRAL · ACTION TO STRIKE / RETURN":notice;
 public override string Standings{get{text.Clear();for(int i=0;i<setup.count;i++)text.Append(setup.players[i].name).Append(" · TEAM ").Append(rules.Team(i)+1).Append(" · ").Append(!rules.alive[i]?"OUT":fighters[i].Cooldown>0?"STRIKE "+fighters[i].Cooldown.ToString("F1")+"s":"STRIKE READY").Append('\n');return text.ToString();}}
 public override string Results=>"TEAM "+(rules.Winner+1)+" WINS DODGEBALL\n\n"+Standings+"\nDrawn rounds: "+Draws;
 public override bool TryReadScoreCard(int card,out string value,out string detail){if(card<0||card>=setup.count){value=detail=null;return false;}int team=rules.Team(card);value=rules.wins[team].ToString();detail=(team==0?"BLUE":"ORANGE")+" TEAM · "+(!rules.alive[card]?"OUT":fighters[card].Cooldown>0?fighters[card].Cooldown.ToString("F1")+"s":"READY");return true;}
 public override bool ValidateSources(out string reason){if(!base.ValidateSources(out reason))return false;int humans=0;for(int i=0;i<setup.count;i++)if(setup.players[i].source!=BowlingSource.AI)humans++;if(humans>4){reason="Up to four local humans; remaining seats use AI.";return false;}return true;}
 public override string ViewText(int index){int slot=views.owners[Mathf.Clamp(index,0,3)];return setup.players[slot].name+" · TEAM "+(rules.Team(slot)+1)+" · "+rules.wins[rules.Team(slot)]+" / 3\n"+(!rules.alive[slot]?"OUT · WATCH YOUR TEAM":Controls(slot)+" · "+(fighters[slot].Cooldown>0?"COOLDOWN":"STRIKE READY"));}
 protected override void BeginGame(){rules.Reset(teamA,teamB);BounceCount=StrikeCount=Eliminations=Returns=StrikeContests=Neutralizations=Draws=GroundContacts=FriendlyContacts=QueuedContacts=ContactPeak=0;var colors=new Color[12];for(int i=0;i<8;i++)colors[i]=setup.players[i].color;for(int i=8;i<colors.Length;i++)colors[i]=Color.white;replay.Colorize(colors);BeginRound();}
 void Layout(){views.Replay=false;views.Layout();if(option==0){views.broadcast.view.enabled=true;views.broadcast.view.rect=new Rect(0,0,1,1);foreach(var camera in views.views)camera.view.enabled=false;cameras=new[]{views.broadcast.view};if(views.weather!=null){views.weather.vendor.AllowCameras.Clear();views.weather.vendor.AllowCameras.Add(views.broadcast.view);}}}
 void BeginRound(){contactCount=0;Clock=0;Timer=3;Stage=DodgeStage.Countdown;notice="READY TO BOUNCE";skip=false;replay.End();for(int i=0;i<8;i++){fighters[i].gameObject.SetActive(i<setup.count);if(i>=setup.count)continue;int team=rules.Team(i),n=team==0?i:i-teamA,count=team==0?teamA:teamB;float x=(n-(count-1)*.5f)*4.8f;var fighter=fighters[i];fighter.truck.body.detectCollisions=true;fighter.ResetFighter(new Vector3(x,.85f,team==0?-9:9),Quaternion.Euler(0,team==0?0:180,0));think[i]=stuck[i]=back[i]=0;seenFlight[i]=seenBall[i]=-1;threatSince[i]=0;ai[i]=Vector2.zero;aiStrike[i]=false;}
 for(int b=0;b<balls.Length;b++){balls[b].ResetBall(new Vector3((b-(balls.Length-1)*.5f)*5,2.4f,0));balls[b].Freeze();}replay.ResetRecord();replayColors.ResetRecord();Layout();Gate();}
 public void Contact(int ball,int target,bool ground,float time,int flight){for(int i=0;i<contactCount;i++)if(contacts[i].ball==ball&&contacts[i].target==target&&contacts[i].ground==ground&&contacts[i].flight==flight){if(time<contacts[i].time)contacts[i].time=time;return;}if(contactCount>=contacts.Length)throw new InvalidOperationException("Dodge contact capacity exceeded; no contact discarded.");contacts[contactCount++]=new BallContact{ball=ball,target=target,ground=ground,time=time,flight=flight};QueuedContacts++;ContactPeak=Mathf.Max(ContactPeak,contactCount);}
 void OrderedContacts(){for(int i=1;i<contactCount;i++){var value=contacts[i];int j=i-1;while(j>=0&&(contacts[j].time>value.time||Mathf.Abs(contacts[j].time-value.time)<.00001f&&value.ground&&!contacts[j].ground)){contacts[j+1]=contacts[j];j--;}contacts[j+1]=value;}
 for(int i=0;i<contactCount;i++){var c=contacts[i];var ball=balls[c.ball];if(c.flight!=ball.Flight)continue;if(c.ground){GroundContacts++;if(ball.Team>=0){Neutralizations++;ball.Neutral();}continue;}if(c.target<0||!rules.alive[c.target])continue;var fighter=fighters[c.target];if(ball.Team==rules.Team(c.target)){FriendlyContacts++;continue;}if(ball.Team<0)continue;if(fighter.CanReturn(ball,c.time)&&ball.Strike(c.target,fighter.Facing,c.time)){fighter.Returned();Returns++;continue;}if(DodgeRules.HitEliminates(ball.Team,rules.Team(c.target),ball.Striker==c.target&&c.time<ball.GraceUntil,false)){if(rules.Eliminate(c.target)){Eliminations++;fighter.Eliminate();}ball.Neutral();}}
 contactCount=0;}
 // Gather every participant's current intent before choosing a single impulse for each ball.
 void ResolveStrikes(float time){foreach(var ball in balls){if(ball.LastStrikeStep==Time.fixedTimeAsDouble)continue;int best=-1,rank=int.MaxValue,contenders=0;float press=float.PositiveInfinity,distance=float.PositiveInfinity;for(int i=0;i<setup.count;i++){if(!rules.alive[i]||!fighters[i].CanReturn(ball,time))continue;contenders++;float candidate=(fighters[i].truck.body.worldCenterOfMass-ball.body.worldCenterOfMass).sqrMagnitude;int order=(i+rules.Round+ball.index)%setup.count;if(DodgeRules.PreferStrike(fighters[i].StrikeStart,candidate,order,press,distance,rank)){best=i;press=fighters[i].StrikeStart;distance=candidate;rank=order;}}if(contenders>1)StrikeContests++;if(best<0)continue;bool returning=ball.Team>=0&&ball.Team!=rules.Team(best);if(ball.Strike(best,fighters[best].Facing,time)){fighters[best].Returned();if(returning)Returns++;}}}

 // AI observes visible balls, then commits one fallible return decision per incoming flight.
 // It cannot reroll a failed reaction every physics step or steal a teammate's outgoing shot.
 void Bot(int slot,float dt){var fighter=fighters[slot];var truck=fighter.truck;var p=truck.body.worldCenterOfMass;float skill=(int)setup.players[slot].difficulty;think[slot]-=dt;aiStrike[slot]=false;stuck[slot]=truck.body.linearVelocity.magnitude<.45f?stuck[slot]+dt:0;if(stuck[slot]>2){back[slot]=.8f;stuck[slot]=0;}back[slot]=Mathf.Max(0,back[slot]-dt);if(think[slot]>0)return;think[slot]=Mathf.Lerp(.24f,.09f,skill*.5f);
 DodgeBall nearest=null;float distance=float.MaxValue,bestBall=float.MaxValue;for(int b=0;b<balls.Length;b++){var candidate=balls[b];if(candidate.Team==rules.Team(slot)&&candidate.body.linearVelocity.sqrMagnitude>9)continue;float d=(candidate.body.worldCenterOfMass-p).sqrMagnitude;float preference=d*(1+.08f*((b+slot)%3));if(preference<bestBall){bestBall=preference;distance=d;nearest=candidate;}}
 int enemy=-1;float best=float.MaxValue;for(int i=0;i<setup.count;i++)if(rules.alive[i]&&rules.Team(i)!=rules.Team(slot)){float d=(fighters[i].truck.body.position-p).sqrMagnitude;if(d<best){best=d;enemy=i;}}var target=nearest!=null?nearest.body.position:Vector3.zero;bool threat=nearest!=null&&nearest.Team>=0&&nearest.Team!=rules.Team(slot);if(nearest!=null&&enemy>=0){var opponent=fighters[enemy].truck.body;var aim=opponent.worldCenterOfMass+Vector3.ProjectOnPlane(opponent.linearVelocity,Vector3.up)*Mathf.Clamp(Vector3.Distance(opponent.worldCenterOfMass,nearest.body.position)/(Clock>=suddenDeath?suddenStrikeSpeed:strikeSpeed),.1f,1.2f)*Mathf.Lerp(.65f,1,skill*.5f);if(!threat){var launchDirection=Vector3.ProjectOnPlane(aim-nearest.body.position,Vector3.up).normalized;var approach=nearest.body.position-launchDirection*2.1f;approach.x=Mathf.Clamp(approach.x,-15.7f,15.7f);approach.z=Mathf.Clamp(approach.z,-11.7f,11.7f);target=Vector3.ProjectOnPlane(approach-p,Vector3.up).sqrMagnitude<1.4f*1.4f&&distance<3.5f*3.5f?aim:approach;}else if(distance<4.8f*4.8f)target=aim;}
 var forward=Vector3.ProjectOnPlane(truck.transform.forward,Vector3.up).normalized;var delta=target-p;delta.y=0;float angle=Vector3.SignedAngle(forward,delta,Vector3.up);float steer=Mathf.Clamp(angle/32,-1,1),throttle=Mathf.Abs(angle)>105?-.7f:Mathf.Abs(angle)>50?.45f:1;if(nearest!=null&&distance<3.5f*3.5f&&Mathf.Abs(angle)<40)throttle=best>13*13?1:.2f;if(throttle<0&&!fighter.Airborne)steer=-steer;if(Mathf.Abs(p.x)>16.2f||Mathf.Abs(p.z)>12.2f){delta=-p;delta.y=0;angle=Vector3.SignedAngle(forward,delta,Vector3.up);steer=Mathf.Clamp(angle/28,-1,1);throttle=Mathf.Abs(angle)>95?-.8f:.65f;if(throttle<0&&!fighter.Airborne)steer=-steer;}if(back[slot]>0){throttle=-.8f;steer=(slot&1)==0?.8f:-.8f;}
 ai[slot]=new Vector2(steer,throttle);if(nearest==null)return;
 if(threat&&distance<7*7&&(seenBall[slot]!=nearest.index||seenFlight[slot]!=nearest.Flight)){seenBall[slot]=nearest.index;seenFlight[slot]=nearest.Flight;threatSince[slot]=Clock;uint hash=unchecked((uint)((slot+1)*73856093^(nearest.Flight+1)*19349663^(rules.Round+1)*83492791));hash^=hash>>13;attemptReturn[slot]=(hash%1000)/1000f<Mathf.Lerp(.42f,.76f,skill*.5f);}
 if(distance<3.5f*3.5f&&Mathf.Abs(nearest.body.position.y-p.y)<2.7f){float shotAngle=enemy>=0?Vector3.SignedAngle(forward,Vector3.ProjectOnPlane(fighters[enemy].truck.body.worldCenterOfMass-p,Vector3.up),Vector3.up):180;float cone=threat?65:Mathf.Lerp(70,40,skill*.5f);bool ready=!threat&&best<13*13||threat&&attemptReturn[slot]&&Clock-threatSince[slot]>=Mathf.Lerp(.32f,.14f,skill*.5f);bool error=!threat&&Mathf.Sin(slot*39+rules.Round*17+Clock*2)>Mathf.Lerp(.65f,.94f,skill*.5f);aiStrike[slot]=ready&&Mathf.Abs(shotAngle)<cone&&!error&&fighter.Cooldown<=0;if(threat&&!aiStrike[slot])ai[slot]=new Vector2(-Mathf.Sign(nearest.body.linearVelocity.x+(slot%2==0?.1f:-.1f)),.7f);}}
 protected override void Simulate(float dt){if(Stage==DodgeStage.Countdown){Timer-=dt;if(Timer<=0){for(int i=0;i<setup.count;i++){fighters[i].truck.body.isKinematic=false;fighters[i].truck.Power(true);}foreach(var ball in balls)ball.Wake();Stage=DodgeStage.Playing;}return;}if(Stage==DodgeStage.Playing){OrderedContacts();Clock+=dt;if(rules.FinishStep()){Resolve();return;}if(Clock>=roundLimit){rules.Draw();Resolve();return;}for(int i=0;i<setup.count;i++)if(rules.alive[i]){Vector2 command=commands[i];bool strike=actions[i];if(setup.players[i].source==BowlingSource.AI){Bot(i,dt);command=ai[i];strike=aiStrike[i];}fighters[i].Step(command,strike,dt);airborne[i]=fighters[i].Airborne;}ResolveStrikes(Time.fixedTime);foreach(var ball in balls)ball.Stamp();int mask=(1<<balls.Length)-1;mask<<=8;for(int i=0;i<setup.count;i++)if(rules.alive[i])mask|=1<<i;replay.Record(Clock,mask);replayColors.Record(Clock);return;}
 if(Stage==DodgeStage.Replay){replayAge+=dt;if(skip||replay.Step(dt)||replayAge>10){replay.End();Stage=DodgeStage.RoundResult;Timer=1.5f;}else replayColors.Draw(replay.Cursor);return;}Timer-=dt;if(Timer<=0){if(rules.Winner>=0)EndMatch();else{rules.NextRound();BeginRound();}}}
 void Resolve(){if(rules.RoundWinner>=0){int team=rules.RoundWinner;ConfirmTeamScore("round:"+rules.Round,team==0?"blue":"orange",team==0?"BLUE TEAM":"ORANGE TEAM",team==0?new Color(.03f,.3f,.9f):SportsBroadcastCanvas.Orange,1,rules.wins[team],"ROUND WON",rules.Winner>=0?SportsScoreTier.MatchChampion:SportsScoreTier.RoundWinner,"WIN",true,rules.Winner>=0);}notice=rules.RoundWinner<0?"DRAW · ROUND REPLAY":"TEAM "+(rules.RoundWinner+1)+" WINS THE ROUND";if(rules.RoundWinner<0)Draws++;replay.Record(Clock+.051f,AliveMask());replayColors.Record(Clock+.051f);for(int i=0;i<setup.count;i++){fighters[i].Freeze();fighters[i].gameObject.SetActive(false);}foreach(var ball in balls){ball.Freeze();ball.gameObject.SetActive(false);}Stage=DodgeStage.Replay;replayAge=0;replay.Begin(Mathf.Max(0,Clock-6));replayColors.Draw(replay.Cursor);feedback.Play(5,0,true);}
 int AliveMask(){int mask=((1<<balls.Length)-1)<<8;for(int i=0;i<setup.count;i++)if(rules.alive[i])mask|=1<<i;return mask;}
 protected override void Present(float dt){if(views==null)return;if(Stage==DodgeStage.Replay&&replay.Playing){views.ReplayView(Vector3.up*2,replay.Angle);return;}if(option==1&&views.Humans>0){views.Follow(dt,airborne);return;}views.broadcast.Pose(Vector3.up*2,new Vector3(0,25,-34),60);fit.arenaBounds=new Bounds(Vector3.up*5,new Vector3(37,12,29));fit.Apply();}
 public override void ExtraAction(string key){if(Stage!=DodgeStage.Replay)return;if(key=="replayangle")replay.Angle=(replay.Angle+1)%3;else if(key=="replayspeed")replay.Speed=replay.Speed==1?.5f:replay.Speed==.5f?2:1;else if(key=="replayrewind"){replay.Seek(Mathf.Max(0,replay.Cursor-3));replayColors.Draw(replay.Cursor);}else if(key=="replayskip")skip=true;ConsumeActions();}
 protected override void StopGame(){replay?.End();contactCount=0;if(fighters!=null)foreach(var fighter in fighters)if(fighter!=null)fighter.Freeze();if(balls!=null)foreach(var ball in balls)if(ball!=null)ball.Freeze();}protected override void StopSounds(){if(fighters!=null)foreach(var fighter in fighters)if(fighter!=null)fighter.truck.StopSound();}
}
